// All numbers are computed here, in code. The model only explains them.
const rows = $input.all().map(i => i.json).filter(r => r.date);
const metrics = ['revenue', 'orders', 'new_customers', 'tickets_opened', 'tickets_closed'];
const day = d => new Date(String(d).slice(0, 10) + 'T00:00:00Z');

const today = new Date(); today.setUTCHours(0, 0, 0, 0);
const thisStart = new Date(today); thisStart.setUTCDate(today.getUTCDate() - 7);
const prevStart = new Date(today); prevStart.setUTCDate(today.getUTCDate() - 14);

const sum = (from, to, m) => rows.filter(r => day(r.date) >= from && day(r.date) < to)
  .reduce((acc, r) => acc + (Number(String(r[m]).replace(',', '.')) || 0), 0);

const table = metrics.map(m => {
  const current = sum(thisStart, today, m), previous = sum(prevStart, thisStart, m);
  const change_pct = previous ? Math.round((current - previous) / previous * 1000) / 10 : null;
  return { metric: m, current: Math.round(current * 100) / 100, previous: Math.round(previous * 100) / 100, change_pct };
});
const [revenue, orders] = [table[0].current, table[1].current];
const avgTicket = orders ? Math.round(revenue / orders * 100) / 100 : null;
const backlogChange = table[3].current - table[4].current;

return [{ json: {
  period: `${thisStart.toISOString().slice(0, 10)} → ${new Date(today - 864e5).toISOString().slice(0, 10)}`,
  table, avg_order_value: avgTicket, ticket_backlog_change: backlogChange, days_with_data: rows.length,
} }];

const schema = {
  type: 'object', additionalProperties: false,
  properties: {
    subject: { type: 'string' },
    headline: { type: 'string' },
    highlights: { type: 'array', items: { type: 'string' } },
    concerns: { type: 'array', items: { type: 'string' } },
    actions: { type: 'array', items: { type: 'string' } },
  },
  required: ['subject', 'headline', 'highlights', 'concerns', 'actions'],
};

return [{ json: {
  ...$json,
  openai_payload: {
    model: $env.OPENAI_MODEL || 'gpt-5.6-luna',
    instructions: 'You write the weekly KPI note for the management team. Use ONLY the numbers given; do not compute new figures ' + '(no new percentages, sums or averages). Max 3 bullets per section, plain business language, in ' + ($env.REPORT_LANGUAGE || 'Spanish') + '.',
    input: 'Computed KPIs (JSON):\n' + JSON.stringify({ period: $json.period, table: $json.table, avg_order_value: $json.avg_order_value, ticket_backlog_change: $json.ticket_backlog_change }),
    text: { format: { type: 'json_schema', name: 'kpi_report', strict: true, schema } },
  },
} }];

function parseResponse(res) {
  const message = (res.output || []).find(o => o.type === 'message');
  const part = message?.content?.find(c => c.type === 'output_text' || c.type === 'refusal');
  if (!part || part.type === 'refusal') throw new Error('The model returned no usable answer: ' + JSON.stringify(res).slice(0, 300));
  return JSON.parse(part.text);
}

const k = $('Compute KPIs in code').item.json;
const r = parseResponse($json);
const fmt = v => v == null ? '—' : Number(v).toLocaleString('es-ES');
const arrow = p => p == null ? '' : p > 0 ? `▲ ${p}%` : p < 0 ? `▼ ${Math.abs(p)}%` : '= 0%';
const rows = k.table.map(t => `<tr><td>${t.metric.replace('_', ' ')}</td><td align="right">${fmt(t.current)}</td>
  <td align="right">${fmt(t.previous)}</td><td align="right">${arrow(t.change_pct)}</td></tr>`).join('');
const list = (title, items) => items.length ? `<h3>${title}</h3><ul>${items.map(i => `<li>${i}</li>`).join('')}</ul>` : '';

const html = `<div style="font-family:Arial,sans-serif;max-width:680px">
<p><b>${r.headline}</b><br><span style="color:#64748b">${k.period}</span></p>
<table cellpadding="6" style="border-collapse:collapse;font-size:14px" border="1" bordercolor="#e2e8f0">
<tr style="background:#f1f5f9"><th align="left">Metric</th><th>This week</th><th>Last week</th><th>Change</th></tr>${rows}</table>
${list('Highlights', r.highlights)}${list('Watch', r.concerns)}${list('Suggested actions', r.actions)}
<p style="color:#94a3b8;font-size:12px">Figures computed by the workflow; text written by AI from those figures.</p></div>`;
return [{ json: { subject: r.subject, html } }];
